CREATE TRIGGER sync_batches_postgres_integers_insert BEFORE INSERT ON sync_batches BEGIN SELECT CASE WHEN typeof(NEW.schema_version) != 'integer' OR NEW.schema_version < -2147483648 OR NEW.schema_version > 2147483647 OR typeof(NEW.metrics_count) != 'integer' OR NEW.metrics_count < -2147483648 OR NEW.metrics_count > 2147483647 OR typeof(NEW.workouts_count) != 'integer' OR NEW.workouts_count < -2147483648 OR NEW.workouts_count > 2147483647 THEN RAISE(ABORT,'postgres integer guard') END; END;
CREATE TRIGGER sync_batches_postgres_integers_update BEFORE UPDATE ON sync_batches BEGIN SELECT CASE WHEN typeof(NEW.schema_version) != 'integer' OR NEW.schema_version < -2147483648 OR NEW.schema_version > 2147483647 OR typeof(NEW.metrics_count) != 'integer' OR NEW.metrics_count < -2147483648 OR NEW.metrics_count > 2147483647 OR typeof(NEW.workouts_count) != 'integer' OR NEW.workouts_count < -2147483648 OR NEW.workouts_count > 2147483647 THEN RAISE(ABORT,'postgres integer guard') END; END;
